/**
 * Represents a performance report generated by PerformanceMonitor.
 */
export interface PerformanceReport {
  avgFps: number;
  lowFps1pct: number;
  jitter: number;
  frameDrops: number;
  heapUsedMb?: number;
}

interface MemoryInfo {
  totalJSHeapSize: number;
  usedJSHeapSize: number;
  jsHeapSizeLimit: number;
}

interface PerformanceWithMemory extends Performance {
  memory?: MemoryInfo;
}

/**
 * Monitors and calculates performance metrics like FPS, jitter, and memory usage.
 */
export class PerformanceMonitor {
  private frameTimes: number[] = [];
  private lastFrameTime = 0;
  private frameDrops = 0;
  private readonly targetFrameTime: number;
  private readonly frameDropThreshold: number;

  constructor(targetFps = 60) {
    this.targetFrameTime = 1000 / targetFps;
    this.frameDropThreshold = this.targetFrameTime * 1.2; // 20% tolerance
  }

  /**
   * Records a frame render timestamp.
   * Call this inside the requestAnimationFrame loop.
   */
  recordFrame(time: number) {
    if (this.lastFrameTime === 0) {
      this.lastFrameTime = time;
      return;
    }
    const delta = time - this.lastFrameTime;
    this.lastFrameTime = time;

    this.frameTimes.push(delta);

    if (delta > this.frameDropThreshold) {
      this.frameDrops++;
    }
  }

  getReport(): PerformanceReport {
    if (this.frameTimes.length === 0) {
      return {
        avgFps: 0,
        lowFps1pct: 0,
        jitter: 0,
        frameDrops: 0,
      };
    }

    const sum = this.frameTimes.reduce((a, b) => a + b, 0);
    const avgFrameTime = sum / this.frameTimes.length;
    const avgFps = 1000 / avgFrameTime;

    // Sort frame times ascending (slowest frames are largest times)
    const sortedFrameTimes = [...this.frameTimes].sort((a, b) => a - b);
    const index = Math.min(
      Math.floor(sortedFrameTimes.length * 0.99),
      sortedFrameTimes.length - 1,
    );
    const lowFrameTime = sortedFrameTimes[index] || avgFrameTime;
    const lowFps1pct = 1000 / lowFrameTime;

    // Jitter: standard deviation of frame times
    const mean = avgFrameTime;
    const squareDiffs = this.frameTimes.map((value) => {
      const diff = value - mean;
      return diff * diff;
    });
    const avgSquareDiff =
      squareDiffs.reduce((a, b) => a + b, 0) / squareDiffs.length;
    const jitter = Math.sqrt(avgSquareDiff);

    const report: PerformanceReport = {
      avgFps: Math.round(avgFps * 100) / 100,
      lowFps1pct: Math.round(lowFps1pct * 100) / 100,
      jitter: Math.round(jitter * 100) / 100,
      frameDrops: this.frameDrops,
    };

    const memory = (performance as PerformanceWithMemory).memory;
    if (memory) {
      report.heapUsedMb =
        Math.round((memory.usedJSHeapSize / (1024 * 1024)) * 100) / 100;
    }

    return report;
  }

  reset() {
    this.frameTimes = [];
    this.frameDrops = 0;
    this.lastFrameTime = 0;
  }
}
